#!/usr/bin/env python3
"""Independently regenerated q0.30 641/801 C1–C7 spectral Taylor data.

The prior Taylor file was TRUNCATED (zlib error -5), not a valid input.
This newer payload was generated by rebuilding q=.30 80-shell physical
spectral nodes in the current investigation, then integrating the exact
piecewise-linear C8 Cauchy formula with fixed spectral crossing anchor.

Each frozen discrete sheet is holomorphic within its local disk. This
DOES NOT establish a unique causal continuum kinetic sheet, a QNM,
or astrophysical observability.
"""
import base64,hashlib,json,zlib
import numpy as np
PAYLOAD_B64=""""""
COMPRESSED_SHA256="c77f689c1f4606f065154175e1879ff6c2397ccb9398586e79d390d4b8120d49"
PHYSICAL_SPECTRAL_SHA={
 "n641_a0":"92e63973d71474b4918fc2c2959227569324f69df7d98addad1838b39e730239",
 "n801_a0":"75a8a9a0a4a0ebd433343ba77a75343a3012ad9a7bb5ba1d1c4fd438222b2da0",
 "n801_am0005":"75a8a9a0a4a0ebd433343ba77a75343a3012ad9a7bb5ba1d1c4fd438222b2da0"
}
def cases():
    compressed=base64.b64decode(PAYLOAD_B64,validate=True)
    actual=hashlib.sha256(compressed).hexdigest()
    if actual!=COMPRESSED_SHA256:
        raise ValueError("Independent regenerated q030 Taylor compressed checksum mismatch")
    d=json.loads(zlib.decompress(compressed))
    if set(d)!=set(PHYSICAL_SPECTRAL_SHA):
        raise ValueError("Missing one of three high-resolution source spectra")
    for key,x in d.items():
        if (x["q"]!=.3 or x["nxi"]!=(641 if key=="n641_a0" else 801)
            or x["source_spectral_sha256"]!=PHYSICAL_SPECTRAL_SHA[key]
            or x["taylor_order"]!=12 or x["strict_validity_radius"]!=.004
            or x["physical_retarded_sheet_uniqueness_proven"] is not False
            or x["holomorphic_discrete_sheet_only"] is not True):
            raise ValueError("Invalid physical Taylor provenance or claims")
        if x["worst_heldout_exact_cauchy_relative"]>1e-9:
            raise ValueError("Taylor fails independent heldout complex-frequency evaluation")
        for name in ("chiJ","chiX"):
            a=np.array([complex(*v) for v in x[name+"_coeff_scaled"]])
            if a.shape!=(13,) or not np.all(np.isfinite(a)):
                raise ValueError("Bad high-resolution Taylor coefficient data")
    return d

def evaluate(case,w):
    w0=complex(*case["center_Momega"])
    dz=(complex(w)-w0)/case["strict_validity_radius"]
    if abs(dz)>1.:
        raise ValueError("Taylor outside independently tested complex-frequency disk")
    coeff=lambda label:np.asarray([complex(*x) for x in case[label+"_coeff_scaled"]])
    return {
        "chiJ":complex(np.polynomial.polynomial.polyval(dz,coeff("chiJ"))),
        "chiX":complex(np.polynomial.polynomial.polyval(dz,coeff("chiX"))),
    }
